```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    printf("Program se izvaja...\n");

    // Prekinitev programa
    printf("Prekinjam program.\n");
    exit(0);

    printf("To se ne bo izvedlo.\n");
    return 0;
}
```

